import {STARTER_PACK} from '../data/offers.js';import {starterEligible,rewardEligible} from '../systems/monetization.js';import {t} from '../locales/index.js';import {icon} from './icons.js';import {button} from './screens.js';
export function starterCard(s,services){if(!starterEligible(s)&&!s.commerce.starterOwned)return '';return `<article class="pack-card"><div class="pack-title"><h3>${t('ui.starter')}</h3>${icon('gift')}</div><p>${t('ui.packDescription')}</p><div class="pack-contents"><div class="pack-content"><span class="pack-art">${icon('gem')}</span>${t('ui.packGems')}</div><div class="pack-content"><span class="pack-art mint-frame">Z</span>${t('ui.packCosmetic')}</div><div class="pack-content"><span class="pack-art">${icon('bolt')}</span>${t('ui.packBoost')}</div><div class="pack-content"><span class="pack-art prop" style="background-position:66.6667% 100%"></span>${t('ui.packDecor')}</div></div>${button(t(s.commerce.starterOwned?'ui.packOwned':services.purchases.available?'ui.testPurchase':'ui.packSoon'),'starter','','button secondary',s.commerce.starterOwned||!services.purchases.available)}<p class="offer-note">${t(services.purchases.test?'ui.testMode':'ui.optional')}</p></article>`;}
export function rewardedCard(s,placement,services){const key=placement[0].toUpperCase()+placement.slice(1);return `<article class="rewarded-row"><h3>${t('ui.ad'+key)}</h3><p>${t('ui.ad'+key+'Info')}</p>${button(t(!services.ads.available?'ui.adsSoon':services.ads.test?'ui.testAd':'ui.watchAd'),'rewarded',placement,'button secondary',!services.ads.available||!rewardEligible(s,placement)||services.busy)}${services.ads.test?`<div class="offer-note">${t('ui.testMode')}</div>`:''}</article>`;}
export function offers(s,services){return starterCard(s,services)+['offline','income','daily','training'].map(p=>rewardedCard(s,p,services)).join('');}
